package ch.xs3.usbphoto;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;import java.io.*;import java.util.*;
public class CopyService extends Service {
 static volatile boolean running=false,scanning=false,cancelled=false;
 static volatile int total=0,done=0,skipped=0,state=0;
 static volatile String current="",failure="";static volatile long bytes=0,size=-1;
 ContentResolver resolver;PowerManager.WakeLock wake;final ArrayList<Job> jobs=new ArrayList<>();
 String t(String en,String fr){return Words.t(this,en,fr);}
 static String status(Context c){if(scanning)return Words.t(c,"Scanning folders…","Analyse des dossiers…");if(state==3)return Words.t(c,"Copy stopped","Copie arrêtée");if(state==4)return Words.t(c,"Copy interrupted","Copie interrompue");if(state==0)return Words.t(c,"Ready","Prêt");return done+Words.t(c," files / "," fichiers / ")+total+Words.t(c," files copied"," fichiers copiés");}
 static String details(Context c){String skip=skipped+Words.t(c," existing files skipped."," fichiers présents ignorés.");if(scanning)return total+Words.t(c," files to copy. "," fichiers à copier. ")+skip;if(state==2)return Words.t(c,"Complete. ","Terminé. ")+skip;if(state>=3)return done+" / "+total+Words.t(c," files copied.\n"," fichiers copiés.\n")+failure;if(state==1)return current+"\n"+(bytes/1048576)+Words.t(c," MB"," Mo")+(size>=0?" / "+(size/1048576)+Words.t(c," MB"," Mo"):"");return "";}
 static class Entry {final Uri uri;final String name,mime;final long length;Entry(Uri u,String n,String m,long l){uri=u;name=CopyRules.safeName(n);mime=m;length=l;}boolean dir(){return DocumentsContract.Document.MIME_TYPE_DIR.equals(mime);}}
 static class Job {final Entry source;final Uri parent;final String path;Job(Entry s,Uri p,String n){source=s;parent=p;path=n;}}
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent intent,int flags,int id){if(running)return START_NOT_STICKY;running=true;scanning=true;cancelled=false;total=done=skipped=0;state=1;failure=current="";jobs.clear();
 NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("copy","Android2USB",NotificationManager.IMPORTANCE_LOW));startForeground(1,notification());resolver=getContentResolver();new Thread(this::runCopy,"android2usb-copy").start();return START_NOT_STICKY;}
 Notification notification(){PendingIntent p=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,"copy").setSmallIcon(R.drawable.ic_transfer).setContentTitle("Android2USB").setContentText(status(this)).setContentIntent(p).setOngoing(running).setOnlyAlertOnce(true).setProgress(Math.max(1,total),done,scanning).build();}
 void notifyProgress(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)return;getSystemService(NotificationManager.class).notify(1,notification());}
 void check()throws IOException{if(cancelled)throw new IOException(t("Copy stopped. Completed files are kept.","Copie arrêtée. Les fichiers terminés sont conservés."));}
 Uri root(String key)throws Exception {String s=getSharedPreferences("config",0).getString(key,"");if(s.isEmpty())throw new IOException(t("Select both folders.","Choisissez les deux dossiers."));Uri tree=Uri.parse(s);return DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));}
 List<Entry> list(Uri parent)throws Exception {check();ArrayList<Entry> entries=new ArrayList<>();Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(parent,DocumentsContract.getDocumentId(parent));String[] columns={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE};
 try(Cursor c=resolver.query(children,columns,null,null,null)){if(c==null)throw new IOException(t("Folder unavailable. Check the USB drive.","Dossier inaccessible. Vérifiez la clé USB."));while(c.moveToNext()){check();entries.add(new Entry(DocumentsContract.buildDocumentUriUsingTree(parent,c.getString(0)),c.getString(1),c.getString(2),c.isNull(3)?-1:c.getLong(3)));}}return entries;}
 void plan(Uri source,Uri target,String prefix,int depth)throws Exception {check();if(depth>128)throw new IOException(t("Too many nested folders.","Trop de niveaux de sous-dossiers."));Map<String,Entry> existing=new HashMap<>();for(Entry e:list(target))existing.put(e.name,e);
 for(Entry e:list(source)){check();String path=prefix+e.name;Entry match=existing.get(e.name);if(e.dir()){Uri child;if(match!=null){if(!match.dir())throw new IOException(t("File/folder conflict: ","Conflit fichier/dossier : ")+path);child=match.uri;}else{child=DocumentsContract.createDocument(resolver,target,DocumentsContract.Document.MIME_TYPE_DIR,e.name);if(child==null)throw new IOException(t("Cannot create folder: ","Impossible de créer le dossier : ")+path);}plan(e.uri,child,path+"/",depth+1);}else if(match!=null){if(match.dir())throw new IOException(t("Folder/file conflict: ","Conflit dossier/fichier : ")+path);skipped++;}else{jobs.add(new Job(e,target,path));total=jobs.size();}}}
 void recover()throws Exception {SharedPreferences p=getSharedPreferences("pending",0);String s=p.getString("uri","");if(s.isEmpty())return;Uri u=Uri.parse(s);
 try(Cursor c=resolver.query(u,new String[]{DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(c==null)throw new IOException(t("Reconnect the drive used for the interrupted copy.","Reconnectez la clé utilisée pour la copie interrompue."));if(c.moveToFirst()&&c.getString(0).startsWith(".android2usb-")){if(!DocumentsContract.deleteDocument(resolver,u))throw new IOException(t("Cannot remove the incomplete file.","Impossible de supprimer le fichier incomplet."));}}
 p.edit().clear().commit();}
 void copy(Job j)throws Exception {check();for(Entry e:list(j.parent))if(e.name.equals(j.source.name))throw new IOException(t("Destination changed. Run the copy again: ","La destination a changé. Relancez la copie : ")+j.path);
 current=j.path;bytes=0;size=j.source.length;Uri temp=null;boolean complete=false;SharedPreferences pending=getSharedPreferences("pending",0);
 try{temp=DocumentsContract.createDocument(resolver,j.parent,"application/octet-stream",".android2usb-"+UUID.randomUUID()+".part");if(temp==null)throw new IOException(t("Cannot create a file on the USB drive.","Impossible de créer un fichier sur la clé USB."));
 if(!pending.edit().putString("uri",temp.toString()).commit())throw new IOException(t("Cannot save recovery information.","Impossible d’enregistrer les informations de reprise."));
 long count=0,last=0;byte[] buffer=new byte[1024*1024];
 try(InputStream in=resolver.openInputStream(j.source.uri);OutputStream out=resolver.openOutputStream(temp,"w")){if(in==null||out==null)throw new IOException(t("Cannot open file.","Impossible d’ouvrir le fichier."));int n;while((n=in.read(buffer))!=-1){check();out.write(buffer,0,n);count+=n;long now=System.currentTimeMillis();if(now-last>150){bytes=count;last=now;}}out.flush();}
 bytes=count;if(j.source.length>=0&&count!=j.source.length)throw new IOException(t("Source size changed during copy: ","La taille source a changé pendant la copie : ")+j.path);
 try(Cursor c=resolver.query(temp,new String[]{DocumentsContract.Document.COLUMN_SIZE},null,null,null)){if(c==null||!c.moveToFirst())throw new IOException(t("Cannot verify the target file.","Impossible de vérifier le fichier cible."));if(!c.isNull(0)&&c.getLong(0)!=count)throw new IOException(t("Target file size is incorrect.","La taille du fichier cible est incorrecte."));}
 check();Uri finished=DocumentsContract.renameDocument(resolver,temp,j.source.name);if(finished==null)throw new IOException(t("The USB drive does not support file finalization.","La clé USB ne permet pas de finaliser le fichier."));complete=true;pending.edit().clear().commit();
 }finally{if(!complete&&temp!=null){try{if(DocumentsContract.deleteDocument(resolver,temp))pending.edit().clear().commit();}catch(Exception ignored){}}}}
 void runCopy(){try{wake=getSystemService(PowerManager.class).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"android2usb:copy");wake.acquire(6*60*60*1000L);Uri source=root("source"),target=root("dest");if(MainActivity.overlap(source,target))throw new IOException(t("Source and destination overlap.","La source et la destination se recouvrent."));recover();plan(source,target,"",0);scanning=false;notifyProgress();for(Job j:jobs){check();copy(j);done++;notifyProgress();}state=2;
 }catch(Exception e){state=cancelled?3:4;failure=t("Check the USB connection and folder access. ","Vérifiez la connexion USB et l’accès aux dossiers. ")+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage());}
 finally{running=false;scanning=false;if(wake!=null&&wake.isHeld())wake.release();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}}
 @Override public void onTimeout(int startId,int type){cancelled=true;stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 @Override public void onDestroy(){cancelled=true;super.onDestroy();}
}
